(137, 'FCV00137', 40, 'Tomentose - Hairy', 'Hairy - A surface covered densely with matted hairs.', NULL, 7, '2026-11-25 00:00:00.000000', '2026-11-25 00:00:00.000000'),
(138, 'FCV00138', 40, 'Hispid - Hairy', 'Hairy - A surface covered with straight bristle-like hairs.', NULL, 7, '2026-11-25 00:00:00.000000', '2026-11-25 00:00:00.000000'),
(139, 'FCV00139', 40, 'Hirsute - Hairy', 'Hairy - A surface covered with slightly stiff and shaggy hairs.', NULL, 7, '2026-11-25 00:00:00.000000', '2026-11-25 00:00:00.000000'),
(140, 'FCV00140', 40, 'Villose - Hairy', 'Hairy - A surface covered with long soft hairs.', NULL, 7, '2026-11-25 00:00:00.000000', '2026-11-25 00:00:00.000000'),
(141, 'FCV00141', 40, 'Strigose - Hairy', 'Hairy - A surface covered with long bristle-like hairs.', NULL, 7, '2026-11-25 00:00:00.000000', '2026-11-25 00:00:00.000000'),
(142, 'FCV00142', 41, 'Straight', 'The margins remain uniform and do not curve.', 'edited 3-8-2023', 7, '2026-11-25 00:00:00.000000', '2026-11-25 00:00:00.000000'),
(143, 'FCV00143', 41, 'Decurved', 'The margins curve slightly downwards.', NULL, 7, '2026-11-25 00:00:00.000000', '2026-11-25 00:00:00.000000'),
(144, 'FCV00144', 41, 'Incurved', 'The margins curve down and inwards.', NULL, 7, '2026-11-25 00:00:00.000000', '2026-11-25 00:00:00.000000'),
(145, 'FCV00145', 41, 'Involute', 'The margins curve downwards and roll inwards. Also known as inrolled.', NULL, 7, '2026-11-25 00:00:00.000000', '2026-11-25 00:00:00.000000'),
(146, 'FCV00146', 41, 'Arched', 'The margins curve upwards between the edge and stem.', NULL, 7, '2026-11-25 00:00:00.000000', '2026-11-25 00:00:00.000000'),
(147, 'FCV00147', 41, 'Uplifted', 'The margins curve upwards. Also known as elevated.', NULL, 7, '2026-11-25 00:00:00.000000', '2026-11-25 00:00:00.000000'),
(148, 'FCV00148', 41, 'Revolute', 'The margins curve inwards and also rolled back..', NULL, 7, '2026-11-25 00:00:00.000000', '2026-11-25 00:00:00.000000'),
(149, 'FCV00149', 41, 'Exceeding', 'The margins extend past the gills.', NULL, 7, '2026-11-25 00:00:00.000000', '2026-11-25 00:00:00.000000'),
(150, 'FCV00150', 42, 'Straight', NULL, NULL, 56, '2026-11-25 00:00:00.000000', '2026-11-25 00:00:00.000000'),
(151, 'FCV00151', 42, 'Undulating', 'Also called: Wavy', NULL, 56, '2026-11-25 00:00:00.000000', '2026-11-25 00:00:00.000000'),
(152, 'FCV00152', 42, 'Appendiculate', 'Remnants of a partial veil hang from the edge of the cap.', NULL, 56, '2026-11-25 00:00:00.000000', '2026-11-25 00:00:00.000000'),
(153, 'FCV00153', 42, 'Incurved', 'Also called: Encurved', NULL, 56, '2026-11-25 00:00:00.000000', '2026-11-25 00:00:00.000000'),
(154, 'FCV00154', 42, 'Decurved', NULL, NULL, 56, '2026-11-25 00:00:00.000000', '2026-11-25 00:00:00.000000'),
(155, 'FCV00155', 42, 'Involute', 'Also called: Inrolled', NULL, 56, '2026-11-25 00:00:00.000000', '2026-11-25 00:00:00.000000'),
(156, 'FCV00156', 42, 'Ciliate', 'Also called: Fringed', NULL, 56, '2026-11-25 00:00:00.000000', '2026-11-25 00:00:00.000000'),
(157, 'FCV00157', 42, 'Arched', NULL, NULL, 56, '2026-11-25 00:00:00.000000', '2026-11-25 00:00:00.000000'),
(158, 'FCV00158', 42, 'Uplifted', NULL, NULL, 56, '2026-11-25 00:00:00.000000', '2026-11-25 00:00:00.000000'),
(159, 'FCV00159', 42, 'Revolute', 'Also called: Rolled Back', NULL, 56, '2026-11-25 00:00:00.000000', '2026-11-25 00:00:00.000000'),
(160, 'FCV00160', 42, 'Split', 'The edges of the cap are split apart or full of large crevices. Also referred to as cracked or rimose.', NULL, 56, '2026-11-25 00:00:00.000000', '2026-11-25 00:00:00.000000'),
(161, 'FCV00161', 42, 'Exceeding Gills', NULL, NULL, 56, '2026-11-25 00:00:00.000000', '2026-11-25 00:00:00.000000'),
(162, 'FCV00162', 42, 'Serrate', NULL, NULL, 56, '2026-11-25 00:00:00.000000', '2026-11-25 00:00:00.000000'),
(163, 'FCV00163', 42, 'Other', NULL, NULL, 56, '2026-11-25 00:00:00.000000', '2026-11-25 00:00:00.000000'),
(164, 'FCV00164', 42, 'Entire', 'There is a smooth transition from the top of the cap to its underside. No irregular attributes should be present on the edges. Also referred to as Smooth, Even, Seamless, Flush, or Regular.', NULL, 7, '2026-11-25 00:00:00.000000', '2026-11-25 00:00:00.000000'),
(165, 'FCV00165', 42, 'Striate', 'Fine and narrow stripes run parallel on the cap margins. The lines will often coincide with the gills underneath the cap. In some cases, the lines are only visible when the cap is wet. Also referred to as striped, furrowed, streaked, ribbed, lined,', NULL, 7, '2026-11-25 00:00:00.000000', '2026-11-25 00:00:00.000000'),
(166, 'FCV00166', 42, 'Sulcate', 'Narrow parallel grooves that line the margins of the cap. Sulcate margins are more defined than striate but less ridged than plicated. Also referred to as plicate-striate.', NULL, 7, '2026-11-25 00:00:00.000000', '2026-11-25 00:00:00.000000'),
(167, 'FCV00167', 42, 'Plicate', 'Parallel pleated margins. They are best described as fan-like or umbrella-like as if the surface of the cap were folded. Plicate margins are more defined and ridged than Striate or Sulcate. Also referred to as pleated or ridged.', NULL, 7, '2026-11-25 00:00:00.000000', '2026-11-25 00:00:00.000000'),
(168, 'FCV00168', 42, 'Eroded', 'Deteriorated, gnawed, or eaten away. The disfigured margins are usually found in older specimens and are the result of insects or deliquescence (common with Ink Caps). Also referred to as gnawed or ragged.', NULL, 7, '2026-11-25 00:00:00.000000', '2026-11-25 00:00:00.000000'),
(169, 'FCV00169', 42, 'Lacerate', 'Many tears mark the edge of the cap. Similar to split margins, however, the cuts are smaller and more frequent. Also referred to as torn.', NULL, 7, '2026-11-25 00:00:00.000000', '2026-11-25 00:00:00.000000'),
(170, 'FCV00170', 42, 'Undulating - Hairy', 'Hairy - The edges of the cap form a wave-like pattern as they rise and fall. Also referred to as wavy irregular or festoony.', NULL, 7, '2026-11-25 00:00:00.000000', '2026-11-25 00:00:00.000000'),
(171, 'FCV00171', 42, 'Crenate - Hairy', 'Hairy - Semi-circle notches or round-toothed edges that are more blunted than serrate margins. Also referred to as scalloped.', NULL, 7, '2026-11-25 00:00:00.000000', '2026-11-25 00:00:00.000000'),
(172, 'FCV00172', 42, 'Serrate - Hairy', 'Hairy - The edges of the cap appear jagged and saw-toothed. More pronounced than crenate margins.', NULL, 7, '2026-11-25 00:00:00.000000', '2026-11-25 00:00:00.000000'),
